<?php

/*
 * Declares the property types of src/Entities/* from the official Webex OpenAPI response schemas.
 *
 *   php tools/webex-spec/entity-types.php <directory with the public-spec json files>
 *
 * For each entity, tools/webex-spec/entity-operations.json lists the operations that return it (generated by
 * running every endpoint). A property gets a nullable type only when every one of those response schemas
 * declares it with the same primitive type: string -> ?string, integer -> ?int, number -> int|float|null,
 * boolean -> ?bool, array -> ?array. Anything else (objects, references, missing or conflicting declarations)
 * stays mixed: a wrong type would make the entity drop a value Webex really returns.
 */

[, $directory] = array_pad($argv, 2, '');
$paths = [];
foreach (glob(rtrim($directory, '/').'/webex-*.json') ?: [] as $file) {
    $spec = json_decode((string) file_get_contents($file), true, flags: JSON_THROW_ON_ERROR);
    foreach ($spec['paths'] ?? [] as $path => $methods) {
        foreach ($methods as $method => $operation) {
            $key = strtoupper($method).' '.rtrim((string) preg_replace('/\{[^}]+\}/', '{}', $path), '/');
            $paths[$key][] = ['spec' => $spec, 'operation' => $operation];
        }
    }
}
if ($paths === []) {
    fwrite(STDERR, "Usage: php tools/webex-spec/entity-types.php <public-spec directory>\n");
    exit(2);
}

$resolve = function (array $spec, array $schema) use (&$resolve): array {
    if (isset($schema['$ref'])) {
        return $resolve($spec, $spec['components']['schemas'][basename($schema['$ref'])] ?? []);
    }
    if (isset($schema['allOf'])) {
        $merged = ['properties' => []];
        foreach ($schema['allOf'] as $part) {
            $merged['properties'] += $resolve($spec, $part)['properties'] ?? [];
        }

        return $merged;
    }

    return $schema;
};
$phpType = fn (array $property): string => match ($property['type'] ?? null) {
    'string' => '?string',
    'integer' => '?int',
    'number' => 'int|float|null',
    'boolean' => '?bool',
    'array' => '?array',
    default => 'mixed',
};

$map = json_decode((string) file_get_contents(__DIR__.'/entity-operations.json'), true, flags: JSON_THROW_ON_ERROR);
$typed = 0;
$kept = 0;
foreach ($map as $class => $operations) {
    $types = [];
    foreach ($operations as $key) {
        foreach ($paths[$key] ?? [] as ['spec' => $spec, 'operation' => $operation]) {
            foreach (['200', '201'] as $status) {
                $schema = $operation['responses'][$status]['content']['application/json']['schema'] ?? null;
                if (! is_array($schema)) {
                    continue;
                }
                $schema = $resolve($spec, $schema);
                $items = $schema['properties']['items'] ?? null;
                if (is_array($items) && ($items['type'] ?? null) === 'array' && isset($items['items'])) {
                    $schema = $resolve($spec, $items['items']);
                }
                foreach ($schema['properties'] ?? [] as $name => $property) {
                    $types[$name][] = $phpType($resolve($spec, $property));
                }
            }
        }
    }

    $file = __DIR__.'/../../src/'.str_replace(['Offlineagency\\LaravelWebex\\', '\\'], ['', '/'], $class).'.php';
    $source = (string) file_get_contents($file);
    $source = (string) preg_replace_callback(
        '/(?:\n    \/\*\*\n     \* @var [^\n]*\n     \*\/|\n    \/\*\* @var [^\n]* \*\/)?\n    public (?:[?\w|]+ )?\$(\w+)(?: = [^;]+)?;/',
        function (array $m) use ($types, &$typed, &$kept): string {
            $candidates = array_values(array_unique($types[$m[1]] ?? ['mixed']));
            $type = count($candidates) === 1 ? $candidates[0] : 'mixed';
            $type === 'mixed' ? $kept++ : $typed++;

            // element types are not validated when an entity is filled: array<mixed> is the honest PHPDoc
            $doc = $type === '?array' ? "\n    /** @var array<mixed>|null */" : '';

            return "{$doc}\n    public {$type} \${$m[1]} = null;";
        },
        $source,
    );
    file_put_contents($file, $source);
}

echo "{$typed} properties typed, {$kept} kept mixed\n";
